mapper.sql:
SELECT tb1.seq /* 접근유형 BIGINT */ , tb1.mb_id /* 회원사ID VARCHAR(20) */ , tb1.mb_nm /* 회사명 VARCHAR(100) */ , tb1.mb_login_id /* 회원사로그인ID VARCHAR(20) */ , tb1.zipcd /* 우편번호 VARCHAR(7) */ , tb1.addr1 /* 주소 VARCHAR(100) */ , tb1.addr2 /* 상세주소 VARCHAR(100) */ , tb1.mb_type /* 회사타입 VARCHAR(4) */ , tb1.use_yn /* 사용여부 VARCHAR(1) */ , tb1.cont_frymd /* 계약시작일 VARCHAR(10) */ , tb1.cont_toymd /* 계약종료일 VARCHAR(10) */ , tb1.corp_reg_num /* 법인등록번호 VARCHAR(12) */ , tb1.tax_reg_num /* 사업자등록번호 VARCHAR(20) */ , tb1.corp_email /* 회사대표이메일 VARCHAR(100) */ , tb1.represent_nm /* 대표명 VARCHAR(30) */ , tb1.telno /* 전화번호 VARCHAR(14) */ , tb1.faxno /* 팩스번호 VARCHAR(14) */ , tb1.domain_url /* 도메인URL VARCHAR(100) */ , tb1.domain_mng /* 도메인관리 VARCHAR(100) */ , tb1.domain_id /* 도메인ID VARCHAR(100) */ , tb1.domain_pw /* 도메인비번 VARCHAR(100) */ , tb1.ci_url /* CI URL VARCHAR(200) */ , tb1.logo_url /* 로고 URL VARCHAR(200) */ , tb1.manager_nm /* 관리자명 VARCHAR(30) */ , tb1.mtelno /* 관리자연락처 VARCHAR(14) */ , tb1.pkg_name /* PKG명 VARCHAR(20) */ , tb1.copy_right /* COPYRIGHT VARCHAR(2000) */ , tb1.certlogo_url /* 증명서사용로고 URL VARCHAR(200) */ , tb1.seal_url /* 직인 URL VARCHAR(200) */ , tb1.certificate_mb_nm /* 증명서 출력용 회사명 VARCHAR(100) */ , tb1.session_time /* 세션시간(분) int(11) */ , tb1.sort_no /* 정렬순서 INT */ , tb1.memo /* 메모 VARCHAR(200) */ , tb1.bigo /* 비고 VARCHAR(100) */ , tb1.in_emp_cd /* 입력자사번 VARCHAR(20) */ , DATE_FORMAT(tb1.in_dtm, '%Y-%m-%d %H:%i:%s') AS in_dtm /* 입력일시 DATETIME */ , tb1.up_emp_cd /* 수정자사번 VARCHAR(20) */ , DATE_FORMAT(tb1.up_dtm, '%Y-%m-%d %H:%i:%s') AS up_dtm /* 수정일시 DATETIME */ , tb2.file_no AS ci_no , tb2.file_nm AS ci_file_nm , tb2.file_size AS ci_file_size , tb3.file_no AS logo_no , tb3.file_nm AS logo_file_nm , tb3.file_size AS logo_file_size , tb4.file_no AS certlogo_no , tb4.file_nm AS certlogo_file_nm , tb4.file_size AS certlogo_file_size , tb5.file_no AS seal_no , tb5.file_nm AS seal_file_nm , tb5.file_size AS seal_file_size , tb14.cd_vl_nm AS use_yn_nm FROM tbsy_member tb1 /* [SY][시스템] 회원사관리 */ LEFT OUTER JOIN tbsy_file_info tb2 ON tb1.mb_id = tb2.mb_id AND tb1.ci_url = tb2.file_url LEFT OUTER JOIN tbsy_file_info tb3 ON tb1.mb_id = tb3.mb_id AND tb1.logo_url = tb3.file_url LEFT OUTER JOIN tbsy_file_info tb4 ON tb1.mb_id = tb4.mb_id AND tb1.certlogo_url = tb4.file_url LEFT OUTER JOIN tbsy_file_info tb5 ON tb1.mb_id = tb5.mb_id AND tb1.seal_url = tb5.file_url LEFT OUTER JOIN (SELECT * FROM tbcm_common_code WHERE grp_cmm_cd = 'USE_YN') tb14 ON tb1.use_yn = tb14.cd_vl AND tb1.mb_id = tb14.mb_id
WHERE tb1.mb_id NOT IN ()
AND tb1.use_yn = #{use_yn}
AND (tb1.mb_login_id LIKE CONCAT('%',UPPER(#{search_word}),'%') OR tb1.mb_login_id LIKE CONCAT('%',LOWER(#{search_word}),'%') OR tb1.mb_login_id LIKE CONCAT('%',#{search_word},'%') OR tb1.mb_nm LIKE CONCAT('%',UPPER(#{search_word}),'%') OR tb1.mb_nm LIKE CONCAT('%',LOWER(#{search_word}),'%') OR tb1.mb_nm LIKE CONCAT('%',#{search_word},'%'))
AND tb1.cont_frymd >= #{srch_term_start_value}
AND tb1.cont_toymd <= #{srch_term_start_value}
AND tb1.cont_frymd <= #{srch_term_end_value}
AND tb1.cont_toymd >= #{srch_term_end_value}

mapper.select:
/* member-mapper.xml selectMemberCount 보험사 중복조회 */
SELECT COUNT(mb_id)
  FROM tbsy_member
 WHERE mb_id = #{mb_id}

mapper.delete:
/* member-mapper.xml deleteMember 회원사관리 삭제  */
DELETE FROM tbsy_member /* [SY][시스템] 회원사관리 */
 WHERE mb_id = #{mb_id}

mapper.select:
		/* member-mapper.xml selectMemberTaxCheck 사업자 번호 중복 확인 */
		SELECT COUNT(mb_id)
		  FROM tbsy_member
		 WHERE tax_reg_num = #{tax_reg_num}
  AND mb_id <> #{mb_id}
